args.new_str:
method calculate_current_counter() -> (uint32) {
    if (!timer_enabled) {
        log info, 4: "Timer not enabled, returning start value: 0x%x", timer_start_value;
        return timer_start_value;
    }

    local cycles_t now = SIM_cycle_count(dev.obj);
    local cycles_t elapsed = now - timer_start_time;
    local uint32 divider = get_step_divider();
    local uint32 decremented = cast(elapsed / divider, uint32);

    log info, 4: "Timer calc: now=%lld, start=%lld, elapsed=%lld, divider=%d, decremented=%d, start_val=%d", 
        now, timer_start_time, elapsed, divider, decremented, timer_start_value;

    if (decremented >= timer_start_value) {
        log info, 4: "Timer expired, returning 0";
        return 0;  // Counter has expired
    }
    local uint32 result = timer_start_value - decremented;
    log info, 4: "Timer current value: 0x%x", result;
    return result;
}

